const std = @import("std");

pub const Theme = struct {
    pub const reset = "\x1b[0m";
    pub const bold = "\x1b[1m";
    pub const gray = "\x1b[90m";

    // 24-bit TrueColor Palette from preview specification
    pub const face = "\x1b[38;2;140;155;170m"; // rgb(140, 155, 170)
    pub const edge = "\x1b[38;2;70;80;92m"; // rgb(70, 80, 92)
    pub const light = "\x1b[38;2;205;212;220m"; // rgb(205, 212, 220)
    pub const ok = "\x1b[38;2;125;165;125m"; // rgb(125, 165, 125)
