    pub fn badgePass(writer: anytype, color: bool) !void {
        if (color) {
            try writer.writeAll(bold ++ ok ++ "[PASS]" ++ reset ++ "   ");
        } else {
            try writer.writeAll("[PASS]   ");
        }
    }

    pub fn badgeFail(writer: anytype, color: bool) !void {
        if (color) {
